use vstd::prelude::*;

verus! {
    // Specification for the concatenation of two arrays
    fn concat(a: &Vec<u64>, b: &Vec<u64>) -> Vec<u64>
        requires
            a.len() <= 100, // Length of the first array must be at most 100
            b.len() <= 100, // Length of the second array must be at most 100
        ensures
            result.len() == a.len() + b.len(), // Resulting array length is the sum of the lengths of the two input arrays
            forall|i: nat| 0 <= i < a.len() ==> result[i] == a[i], // Elements from the first array are preserved
            forall|i: nat| a.len() <= i < result.len() ==> result[i] == b[i - a.len()] // Elements from the second array are preserved
    {
        let mut result: Vec<u64> = Vec::new();
        result.resize(a.len() + b.len(), 0); // Preallocate space for the result vector

        // Copy elements from the first vector
        let mut i: usize = 0;
        while i < a.len()
            invariant
                i <= a.len(),
                forall|j: nat| 0 <= j < i ==> result[j] == a[j],
                result.len() == a.len() + b.len(),
        {
            result[i] = a[i];
            i = i + 1;
        }

        // Copy elements from the second vector
        let mut j: usize = 0;
        while j < b.len()
            invariant
                j <= b.len(),
                forall|k: nat| 0 <= k < j ==> result[i + k] == b[k],
                result.len() == a.len() + b.len(),
        {
            result[i + j] = b[j];
            j = j + 1;
        }

        result
    }
}

